<script>(()=>{'use strict';const $=(s,c=document)=>c.querySelector(s),$$=(s,c=document)=>[...c.querySelectorAll(s)],body=document.body,menu=$('#mobileMenu'),sheet=$('#dateSheet'),share=$('#shareModal'),toast=$('#toast');const openMenu=()=>{menu.classList.add('open');menu.setAttribute('aria-hidden','false');body.style.overflow='hidden'},closeMenu=()=>{menu.classList.remove('open');menu.setAttribute('aria-hidden','true');body.style.overflow=''};$('#menuOpen')?.addEventListener('click',openMenu);$('#menuClose')?.addEventListener('click',closeMenu);const showToast=(a,b)=>{$('#toastTitle').textContent=a;$('#toastText').textContent=b;toast.classList.add('show');clearTimeout(showToast.t);showToast.t=setTimeout(()=>toast.classList.remove('show'),2800)};const openSheet=()=>{sheet.classList.add('open');sheet.setAttribute('aria-hidden','false');body.style.overflow='hidden'},closeSheet=()=>{sheet.classList.remove('open');sheet.setAttribute('aria-hidden','true');body.style.overflow=''};$('#changeDateButton')?.addEventListener('click',openSheet);$$('[data-close-sheet]').forEach(b=>b.addEventListener('click',closeSheet));$$('.date-option').forEach(b=>b.addEventListener('click',()=>{$$('.date-option').forEach(x=>x.classList.remove('active'));b.classList.add('active')}));$('#confirmDate')?.addEventListener('click',()=>{closeSheet();showToast('Data a fost actualizată','Confirmarea demonstrativă a fost salvată.')});const openModal=()=>{share.classList.add('open');share.setAttribute('aria-hidden','false');body.style.overflow='hidden'},closeModal=()=>{share.classList.remove('open');share.setAttribute('aria-hidden','true');body.style.overflow=''};$('#shareButton')?.addEventListener('click',openModal);$$('[data-close-modal]').forEach(b=>b.addEventListener('click',closeModal));share?.addEventListener('click',e=>{if(e.target===share)closeModal()});$('#shareForm')?.addEventListener('submit',e=>{e.preventDefault();const mail=$('#shareEmail').value.trim();if(!mail)return;closeModal();e.target.reset();showToast('Bilet trimis',`Linkul a fost trimis la ${mail}.`)});$('#copyCode')?.addEventListener('click',async()=>{try{await navigator.clipboard.writeText($('#ticketCode').textContent);showToast('Cod copiat','Poți folosi codul și manual la acces.')}catch{showToast('Cod bilet','NV-1842-A01')}});$('#walletButton')?.addEventListener('click',()=>showToast('Adăugat în Wallet','Biletul este disponibil și offline.'));$('#downloadButton')?.addEventListener('click',()=>showToast('PDF pregătit','Fișierul demonstrativ a fost generat.'));$('#editBeneficiary')?.addEventListener('click',()=>showToast('Beneficiar', 'Modificarea beneficiarului va fi disponibilă în profil.'));$('#supportChat')?.addEventListener('click',()=>showToast('Chat deschis','Un consultant demonstrativ este disponibil.'));$('#notificationButton')?.addEventListener('click',()=>showToast('Notificări','Nu ai notificări noi.'));document.addEventListener('keydown',e=>{if(e.key==='Escape'){closeMenu();closeSheet();closeModal()}});if(!matchMedia('(prefers-reduced-motion: reduce)').matches){$$('.detail-copy > *').forEach((el,i)=>el.animate([{opacity:0,transform:'translateY(20px)'},{opacity:1,transform:'translateY(0)'}],{duration:560,delay:60+i*70,easing:'cubic-bezier(.22,.8,.2,1)',fill:'both'}));const r=$('#mapRoute');if(r){const l=r.getTotalLength();r.style.strokeDasharray=l;r.style.strokeDashoffset=l;r.animate([{strokeDashoffset:l},{strokeDashoffset:0}],{duration:1700,delay:250,easing:'cubic-bezier(.22,.8,.2,1)',fill:'forwards'})}const o=new IntersectionObserver(es=>es.forEach(e=>{if(e.isIntersecting){e.target.animate([{opacity:0,transform:'translateY(16px)'},{opacity:1,transform:'translateY(0)'}],{duration:500,easing:'cubic-bezier(.22,.8,.2,1)',fill:'both'});o.unobserve(e.target)}}),{threshold:.1});$$('.panel,.support-banner').forEach(el=>o.observe(el))}})();</script>
<script>
(function(){
  function nvAuth(){ try { return JSON.parse(localStorage.getItem('nordvale_auth')||'null'); } catch(e){ return null; } }
  var a = nvAuth();
  if(!a || !a.token){ location.href='/autentificare?next='+encodeURIComponent(location.pathname+location.search); return; }
  var AH = { 'Authorization':'Bearer '+a.token };
  function api(ac,opt){ opt=opt||{}; opt.headers=Object.assign({},AH,opt.headers||{}); return fetch('/api/proxy.php?action='+ac,opt).then(function(r){return r.json().catch(function(){return{};});}).catch(function(){return{};}); }
  function post(ac,b){ return api(ac,{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(b||{})}); }
  function initials(n){ n=(n||'').trim(); if(!n)return 'N'; var p=n.split(/\s+/); return (((p[0]||'')[0]||'')+((p[1]||'')[0]||'')).toUpperCase()||'N'; }
  function fmtDate(iso){ if(!iso)return ''; var d=new Date(iso); if(isNaN(d))return ''; return d.toLocaleDateString('ro-RO',{day:'2-digit',month:'short',year:'numeric'}); }
  function hydrateUser(u){ if(!u)return; var name=u.name||(((u.first_name||'')+' '+(u.last_name||'')).trim())||'Cont Nordvale'; window.__nvName=name; var box=document.querySelector('.profile-mini'); if(box){ var av=box.querySelector('.avatar'); if(av)av.textContent=initials(name); var st=box.querySelector('strong'); if(st)st.textContent=name; } }
  document.querySelectorAll('a,button').forEach(function(el){ if((el.textContent||'').trim()==='Deconectare'){ el.addEventListener('click',function(ev){ ev.preventDefault(); post('logout').finally(function(){ localStorage.removeItem('nordvale_auth'); location.href='/'; }); }); } });
  hydrateUser(a.user);
  api('me').then(function(d){ if(d&&d.success&&d.data){ a.user=Object.assign({},a.user,d.data); try{localStorage.setItem('nordvale_auth',JSON.stringify(a));}catch(e){} hydrateUser(a.user); } });

  var code=new URLSearchParams(location.search).get('code');
  api('acc-tickets').then(function(d){ if(!(d&&d.success&&d.data))return; var all=(d.data.upcoming||[]).concat(d.data.past||[]); if(!all.length)return; var t=code?all.filter(function(x){return x.code===code;})[0]:all[0]; if(!t)return; var nm=window.__nvName||'Bilet';
    var chs=document.querySelectorAll('.credential-head strong'); if(chs[0])chs[0].textContent=nm;
    var cc=document.querySelector('#ticketCode'); if(cc&&t.code)cc.textContent=t.code;
    var dm=document.querySelectorAll('.detail-meta strong'); if(dm[0]&&t.date)dm[0].textContent=fmtDate(t.date); if(dm[2]&&t.venue)dm[2].textContent=t.venue;
    var bcr=document.querySelector('.breadcrumb span:last-child'); if(bcr&&t.code)bcr.textContent=t.code;
    var idn=document.querySelector('.identity strong'); if(idn)idn.textContent=nm;
    var idm=document.querySelector('.identity span span'); if(idm&&a.user&&a.user.email)idm.textContent=a.user.email+' · beneficiar';
    var qh=document.querySelector('.qr-hero'); if(qh&&window.QRCode){ qh.style.backgroundImage='none'; qh.innerHTML=''; var cv=document.createElement('canvas'); cv.style.maxWidth='100%'; qh.appendChild(cv); window.QRCode.toCanvas(cv, t.code||' ', {width:170,margin:1}, function(){}); }
  });
})();
</script>
